ss=&quot;NormalTextRun SCXW193608524 BCX0&quot;&gt;France&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW193608524 BCX0&quot;&gt; and other markets&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW193608524 BCX0&quot;&gt;, and be&lt;/span&gt; &lt;/span&gt;&lt;span class=&quot;TextRun SCXW193608524 BCX0&quot; lang=&quot;EN-US&quot; data-contrast=&quot;none&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW193608524 BCX0&quot;&gt;the go-to person for your &lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW193608524 BCX0&quot;&gt;area of the &lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW193608524 BCX0&quot;&gt;product.&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;Business outcome ownership&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;: define measurable goals and KPIs (adoption, quality, satisfaction) for your area and drive outcome&lt;/span&gt;‑&lt;span data-contrast=&quot;none&quot;&gt;oriented delivery.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559685&amp;quot;:1080,&amp;quot;335559738&amp;quot;:30,&amp;quot;335559739&amp;quot;:30,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
